            animate={{ scale: 1, opacity: 1 }}
            transition={{ type: 'spring', stiffness: 500, damping: 25 }}
            className="absolute -top-1 -right-1 w-6 h-6 bg-emerald-500 rounded-full text-white flex items-center justify-center shadow-md z-30"
