// --- Orbiting Circles Subcomponent ---
interface OrbitingCirclesProps {
  className?: string;
  children?: React.ReactNode;
  reverse?: boolean;
  duration?: number;
  delay?: number;
  radius?: number;
  path?: boolean;
  isGlobeMode?: boolean;
  isPaused?: boolean;
  speedMultiplier?: number;
}

export function OrbitingCircles({
  className,
  children,
  reverse = false,
  duration = 20,
  delay = 0,
  radius = 120,
  path = true,
  isGlobeMode = true,
  isPaused = false,
  speedMultiplier = 1,
}: OrbitingCirclesProps) {
  const calculatedDuration = Math.max(2, duration / speedMultiplier);

  return (
    <>
      {/* SVG Dashed Orbit Line */}
      {path && (
        <svg
